-- CODIA · Actualizacion listado asambleistas (Lista 2026-2027, 90 personas)
-- Hace cedula y colegiatura opcionales (la lista nueva no trae cedula).
alter table asambleistas alter column cedula drop not null;
alter table asambleistas alter column colegiatura drop not null;
truncate table asistencia, asambleistas restart identity cascade;
